/**
 * StateSpaceModel — the top-level orchestrator.
 *
 * Holds all 5 layers, the AutoLing engine, the tool registry,
 * and the ChangingLineEngine that drives everything.
 *
 * Architecture:
 *   Layer 0 — KnowledgeGraph  (Fu Xi)
 *   Layer 1 — CausalGraph     (Mawangdui)
 *   Layer 2 — StateSpace      (King Wen)  ← the "live" reading layer
 *   Layer 3 — TemporalGraph   (Reverse Fu Xi)
 *   Layer 4 — DependencyGraph (Complement Fu Xi)
 *
 * All 5 layers share the same 64 hexagram nodes (by fuxi value) but each
 * instantiates its own HexagramNode with independent phase state and edges.
 */

import { KnowledgeGraph }  from './layers/KnowledgeGraph.js';
import { CausalGraph }     from './layers/CausalGraph.js';
import { StateSpace }      from './layers/StateSpace.js';
import { TemporalGraph }   from './layers/TemporalGraph.js';
import { DependencyGraph } from './layers/DependencyGraph.js';
import { ChangingLineEngine } from './ChangingLineEngine.js';
import { AutoLing }        from '../generators/AutoLing.js';
import { HEXAGRAMS, BY_FUXI } from '../data/hexagrams.js';
import { SEQUENCES, SEQUENCE_IDS } from '../data/sequences.js';

export class StateSpaceModel {
  constructor() {
    console.log('[StateSpaceModel] building 5-layer state space...');

    this.layers = [
      new KnowledgeGraph(),
      new CausalGraph(),
      new StateSpace(),
      new TemporalGraph(),
      new DependencyGraph(),
    ];

    this.layerMap = new Map(this.layers.map(l => [l.id, l]));

    // Tool registry — all generated tools across all instances
    this.toolRegistry = new Map();

    // AutoLing engine — learns code and language, generates tools
    this.autoLing = new AutoLing();

    // Changing line engine — drives simulation and dispatches to AutoLing
    this.engine = new ChangingLineEngine(this);

    console.log(`[StateSpaceModel] ${this.layers.length} layers, 64 nodes each`);
    console.log('[StateSpaceModel] AutoLing initialized');
  }

  /**
   * Start the simulation.
   */
  start(tickMs = 150) {
    this.engine.start(tickMs);
    console.log('[StateSpaceModel] running');
  }

  stop() { this.engine.stop(); }

  getLayer(id) { return this.layerMap.get(id); }

  /**
   * Feed text or code into AutoLing for learning.
   * All layers' nodes will eventually benefit as new tools get generated.
   */
  learn(text, language = null) {
    return this.autoLing.learn(text, language);
  }

  /**
   * Manually trigger a changing-line event on a specific node.
   */
  trigger(fuxi, lineIndex, layerId = 'kingwen') {
    this.engine.trigger(fuxi, lineIndex, layerId);
  }

  /**
   * Subscribe to events from the engine.
   */
  on(event, fn) { this.engine.on(event, fn); }

  /**
   * Get full model state for API / visualization.
   */
  getState() {
    return {
      layers: this.layers.map(l => ({
        id: l.id,
        name: l.name,
        description: l.description,
        layerIndex: l.layerIndex,
        nodeCount: l.nodes.size,
        edgeCount: l.edges.length,
        topEnergy: Array.from(l.nodes.values())
          .sort((a, b) => b.energy - a.energy)
          .slice(0, 5)
          .map(n => ({ fuxi: n.fuxi, name: n.name, char: n.char, energy: n.energy })),
      })),
      toolCount: this.toolRegistry.size,
      autoLing: this.autoLing.getStats(),
      eventLog: this.engine.getLog(20),
    };
  }

  /**
   * Get a single layer's full graph data (nodes + edges) for visualization.
   */
  getLayerGraph(layerId) {
    const layer = this.layerMap.get(layerId);
    if (!layer) return null;

    const nodes = Array.from(layer.nodes.values()).map(n => ({
      id: n.fuxi,
      kw: n.kw,
      name: n.name,
      char: n.char,
      keyword: n.keyword,
      lower: n.lower,
      upper: n.upper,
      sequenceRank: n.sequenceRank,
      energy: n.energy,
      phase: n.phase.map(p => ({
        axis: p.axis,
        value: p.value,
        changing: p.changing,
        changingType: p.changingType,
      })),
      changingLines: n.phase.filter(p => p.changing).map(p => ({
        line: p.axis, type: p.changingType, value: p.value,
      })),
      toolCount: n.tools.length,
    }));

    const edges = layer.edges.map(e => ({
      source: e.source,
      target: e.target,
      weight: e.weight,
      type: e.type,
      directed: e.directed || false,
    }));

    return {
      id: layer.id,
      name: layer.name,
      description: layer.description,
      layerIndex: layer.layerIndex,
      nodes,
      edges,
    };
  }

  /**
   * Get all tools (generated by AutoLing across all layers).
   */
  getTools(limit = 50) {
    return Array.from(this.toolRegistry.values())
      .sort((a, b) => b.createdAt - a.createdAt)
      .slice(0, limit);
  }

  /**
   * Get a node's full state across all 5 layers.
   */
  getNodeAcrossLayers(fuxi) {
    const hex = BY_FUXI[fuxi];
    if (!hex) return null;
    return {
      hexagram: hex,
      layers: this.layers.map(l => {
        const node = l.getNode(fuxi);
        return node ? { layerId: l.id, layerName: l.name, ...node.toJSON() } : null;
      }).filter(Boolean),
    };
  }

  /**
   * Drain AutoLing mesh queue (for P2P distribution).
   */
  drainMeshQueue() {
    return this.autoLing.drainMeshQueue();
  }

  /**
   * Receive mesh item from another instance.
   */
  receiveFromMesh(item) {
    this.autoLing.receiveFromMesh(item);
  }
}
